/// <summary>
/// Extension class of form data source SalesTable in form SalesTable
/// </summary>
[ExtensionOf(formDataSourceStr(SalesTable, SalesTable))]
public final class METSalesTableFormSalesTableDS_Extension
{
}

Method.Source:
    /// <summary>
    /// Write the record
    /// </summary>
    void write()
    {
        FormDataSource metSalesTable_ds;
        METSalesTable metSalesTableLoc;
        SalesTable salesTableLoc;
        
        metSalesTable_ds = this.formRun().dataSource(formDataSourceStr(SalesTable, METSalesTable));

        if (metSalesTable_ds)
        {
            salesTableLoc = this.cursor();
            metSalesTableLoc = metSalesTable_ds.cursor();
            salesTableLoc.metPackMETSalesTable(metSalesTableLoc);
        }
        next write();
    }

    /// <summary>
    /// active method on ST datasource
    /// </summary>
    /// <returns>
    /// int
    /// </returns>
    int active()
    {
        int ret = next active();

        SalesTable salesTable = this.cursor() as SalesTable;
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCancellation))).enabled(salesTable.SalesStatus == SalesStatus::Canceled);
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METTMSEngineSalesOrderCreation))).enabled((salesTable.SalesStatus != SalesStatus::Canceled)&&
                                            (salesTable.DocumentStatus == DocumentStatus::None || salesTable.DocumentStatus == DocumentStatus::Confirmation) && 
                                            (salesTable.METOrderExtractStatus != METOrderExtractStatus::Extracted));
        
        this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, METAllowBackOrders))).enabled(false);

        if (salesTable.DataAreaId != VendParameters::find().METInterCompanyLegalEntity)
        {
            this.formRun().control(this.formRun().controlId(formControlStr(SalesTable, SalesTable_METIntercompanyTransferFulfillment))).enabled(false);
        }

        return ret;
    }
